gDJ(){return"\u0644\u0627\u0639\u0628 \u062a\u0639\u0627\u0642\u062f\u062a \u0645\u0639\u0647 \u062d\u062f\u064a\u062b\u064b\u0627: \u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d\u0647 \u0642\u0631\u064a\u0628 \u062d\u0627\u0644\u064a\u064b\u0627 \u0645\u0646 \u0645\u0628\u0644\u063a \u0634\u0631\u0627\u0626\u0647\u060c \u0648\u0645\u0639 \u0627\u0644\u0648\u0642\u062a \u064a\u0639\u0643\u0633 \u0642\u064a\u0645\u062a\u0647 \u0627\u0644\u0633\u0648\u0642\u064a\u0629."},
gPz(){return"\u0645\u0646 \u064a\u062a\u0648\u0644\u0649 \u0627\u0644\u0628\u064a\u0639\u061f"},
gaMf(){return"\u0625\u0646 \u0628\u064a\u0639 \u064a\u0635\u0644\u0643"},
gaMe(){return"\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0633\u0648\u0642\u064a\u0629"},
gaM6(){return"\u062f\u0627\u0626\u0631\u0629 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u0623\u0646\u062f\u064a\u0629"},
gaM5(){return"\u0645\u0627 \u064a\u0635\u0644\u0643 \u0645\u0646 \u062d\u0635\u0629"},
aMv(a,b,c){return"\u0633\u064a\u064f\u0639\u0631\u0636 "+a+" \u0641\u064a \u0627\u0644\u0645\u0632\u0627\u062f \u0628\u062a\u0645\u062b\u064a\u0644 \u0645\u0646 "+b+"\u060c \u0628\u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d "+c+"."},
